import os
import re
import operator

def evaluate_expression(expr, items):
    # Replace items[i] with the corresponding value
    for i in range(len(items)):
        expr = expr.replace(f"items[{i}]", str(items[i]))

    # Tokenize the expression into numbers, operators, and parentheses
    tokens = re.findall(r'(\d+|[+\-*/()])', expr)
    tokens = [t for t in tokens if t.strip() != '']

    # Convert tokens to numbers where possible
    token_values = []
    for token in tokens:
        if token.isdigit():
            token_values.append(int(token))
        else:
            token_values.append(token)

    # Evaluate the expression using a stack-based approach
    def evaluate(tokens):
        stack = []
        ops = []
        for token in tokens:
            if token.isdigit():
                stack.append(int(token))
            elif token in '+-*/':
                while ops and ops[-1] != '(' and (
                    (token in '+-' and ops[-1] in '+-*/') or
                    (token in '*/' and ops[-1] in '*/')
                ):
                    op = ops.pop()
                    b = stack.pop()
                    a = stack.pop()
                    if op == '+':
                        stack.append(a + b)
                    elif op == '-':
                        stack.append(a - b)
                    elif op == '*':
                        stack.append(a * b)
                ops.append(token)
            elif token == '(':
                ops.append(token)
            elif token == ')':
                while ops and ops[-1] != '(':
                    op = ops.pop()
                    b = stack.pop()
                    a = stack.pop()
                    if op == '+':
                        stack.append(a + b)
                    elif op == '-':
                        stack.append(a - b)
                    elif op == '*':
                        stack.append(a * b)
                ops.pop()  # Remove '('
        while ops:
            op = ops.pop()
            b = stack.pop()
            a = stack.pop()
            if op == '+':
                stack.append(a + b)
            elif op == '-':
                stack.append(a - b)
            elif op == '*':
                stack.append(a * b)
        return stack[0] if stack else 0

    return evaluate(token_values)

