import sys
import json
import os
import re
import math
from typing import List, Dict, Any

def evaluate_expression(expr: str, items: List[int]) -> int:
    # Replace items[i] with the corresponding item value
    def replace_items(match):
        i = int(match.group(1))
        return str(items[i])

    expr = re.sub(r'items\[(\d+)\]', replace_items, expr)

    # Tokenize the expression into numbers, operators, and parentheses
    tokens = re.findall(r'(\d+|[+\-*/()])', expr)

    # Convert tokens to postfix notation (Reverse Polish Notation)
    output = []
    operators = []

    for token in tokens:
        if token.isdigit():
            output.append(int(token))
        elif token in '+-*/':
            while (operators and operators[-1] != '(' and
                   ((token in '+-' and operators[-1] in '+-*/') or
                    (token in '*/' and operators[-1] in '*/'))):
                output.append(operators.pop())
            operators.append(token)
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators and operators[-1] != '(':
                output.append(operators.pop())
            operators.pop()  # Remove the '('

    while operators:
        output.append(operators.pop())

    # Evaluate the postfix expression
    stack = []
    for token in output:
        if isinstance(token, int):
            stack.append(token)
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)

    return stack[0]

def main():
    if len(sys.argv) != 2:
        print("Usage: python render.py <json_file>", file=sys.stderr)
        sys.exit(1)

    json_file = sys.argv[1]
    if not os.path.exists(json_file):
        print(f"Error: File {json_file} does not exist.", file=sys.stderr)
        sys.exit(1)

    try:
        with open(json_file, 'r') as f:
            data = json.load(f)
    except json.JSONDecodeError:
        print("Error: Invalid JSON file.", file=sys.stderr)
        sys.exit(1)

    if 'items' not in data or 'template' not in data:
        print("Error: JSON must contain 'items' and 'template' fields.", file=sys.stderr)
        sys.exit(1)

    items = data['items']
    template = data['template']

    auth_token = os.getenv('AUTH_TOKEN')
    if not auth_token:
        print("Error: AUTH_TOKEN environment variable not set.", file=sys.stderr)
        sys.exit(1)

    tokens_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'tokens.txt')
    if not os.path.exists(tokens_path):
        print(f"Error: File {tokens_path} does not exist.", file=sys.stderr)
        sys.exit(1)

    with open(tokens_path, 'r') as f:
        tokens = [line.strip() for line in f.readlines()]

    if not any(token == auth_token for token in tokens):
        print("UNAUTHORIZED", file=sys.stderr)
        sys.exit(1)

    result = template
    for match in re.finditer(r'\{\{([^}]+)\}\}', template):
        expr = match.group(1)
        try:
            value = evaluate_expression(expr, items)
            result = result.replace(match.group(0), str(value))
        except Exception:
