import sys
import json
import os
import re
import ast
import math

def validate_token():
    auth_token = os.getenv('AUTH_TOKEN')
    if not auth_token:
        print("UNAUTHORIZED", file=sys.stderr)
        sys.exit(1)

    tokens = []
    with open('tokens.txt', 'r') as f:
        for line in f:
            stripped = line.rstrip('\n')
            tokens.append(stripped)

    if auth_token not in tokens:
        print("UNAUTHORIZED", file=sys.stderr)
        sys.exit(1)

def parse_expression(expr_str, items):
    try:
        # Replace items[i] with a function call
        def items_ref(i):
            try:
                return items[int(i)]
            except IndexError:
                raise ValueError(f"Index {i} out of range")

        # Replace all occurrences of items[i] with a lambda
        def replace_items(match):
            i = match.group(1)
            return str(items_ref(i))

        # Use regex to replace items[i] with a callable
        expr = re.sub(r'items\[(\d+)\]', replace_items, expr_str)

        # Parse and evaluate the expression safely
        parsed_expr = ast.parse(expr, mode='eval')
        # Create a namespace for the eval
        namespace = {
            '__builtins__': None,
            'items': items,
            'math': math
        }
        # Evaluate the expression
        result = eval(ast.unparse(parsed_expr), namespace)
        return result
    except Exception:
        raise ValueError(f"Invalid expression: {expr_str}")

def main():
    if len(sys.argv) != 2:
        print("Usage: python render.py <json_file>", file=sys.stderr)
        sys.exit(1)

    json_file = sys.argv[1]
    try:
        with open(json_file, 'r') as f:
            data = json.load(f)
    except json.JSONDecodeError:
        print("Invalid JSON file", file=sys.stderr)
        sys.exit(1)

    if 'items' not in data or 'template' not in data:
        print("Invalid JSON format: missing 'items' or 'template'", file=sys.stderr)
        sys.exit(1)

    validate_token()
    items = data['items']
    template = data['template']

    # Replace all {{expr}} with evaluated expressions
    def replace_expr(match):
        expr = match.group(1)
        try:
            return str(parse_expression(expr, items))
        except ValueError as e:
            print(f"Error evaluating expression: {e}", file=sys.stderr)
            sys.exit(1)

    processed_template = re.sub(r'\{\{([^}]+)\}\}', replace_expr, template)
    print(processed_template)

if __name__ == "__main__":
    main()
